<?php
 namespace Pterodactyl\Services\Dezerx\Subdomains; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Schema; use Pterodactyl\Services\Dezerx\Settings; class Subdomains { public const KEY = 'subdomains'; public const DEFAULT_MAX = 1; public static function all(): array { $stored = Settings::get(self::KEY) ?? []; return [ 'cloudflare_token' => trim((string) ($stored['cloudflare_token'] ?? '')), 'max_per_server' => max(0, (int) ($stored['max_per_server'] ?? self::DEFAULT_MAX)), ]; } public static function maxPerServer(): int { return self::all()['max_per_server']; } public static function save(?string $token, int $maxPerServer): void { $current = self::all(); Settings::put(self::KEY, [ 'cloudflare_token' => $token === null || trim($token) === '' ? $current['cloudflare_token'] : trim($token), 'max_per_server' => max(0, min(25, $maxPerServer)), ]); } public static function clearToken(): void { Settings::put(self::KEY, [...self::all(), 'cloudflare_token' => '']); } public static function available(): bool { if (self::all()['cloudflare_token'] === '') { return false; } try { return Schema::hasTable('dezerx_subdomain_domains') && DB::table('dezerx_subdomain_domains')->where('enabled', true)->exists(); } catch (\Throwable) { return false; } } public static function payload(): array { return ['available' => self::available()]; } } 